head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


scwin.fn_GetPar, scwin.fn_SetPar;
scwin.keyIsurCd, scwin.keyGubun;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// dts_code의 인덱스에 해당하는 값을 dts_selectleadcom에 add한다.
scwin.fn_add_dts_select = function(add_index) {
    dts_selectleadcom.insertRow();
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISU_CD", dts_code.getCellData(add_index, "ISU_CD"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISU_NM", dts_code.getCellData(add_index, "ISU_NM"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISUR_CD", dts_code.getCellData(add_index, "ISUR_CD"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISUR_NM", dts_code.getCellData(add_index, "ISUR_NM"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "COM_NM", dts_code.getCellData(add_index, "COM_NM"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "LIST_DD", dts_code.getCellData(add_index, "LIST_DD"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "LSTTRD_DD", dts_code.getCellData(add_index, "LSTTRD_DD"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "EXP_DD", dts_code.getCellData(add_index, "EXP_DD"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ETN_ISU_PRC", dts_code.getCellData(add_index, "ETN_ISU_PRC"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ETN_ISU_QTY", dts_code.getCellData(add_index, "ETN_ISU_QTY"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISU_PRC", dts_code.getCellData(add_index, "ISU_PRC"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISU_SHRS", dts_code.getCellData(add_index, "ISU_SHRS"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "BFCHG_EXER_PRC", dts_code.getCellData(add_index, "BFCHG_EXER_PRC"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "AFCHG_EXER_PRC", dts_code.getCellData(add_index, "AFCHG_EXER_PRC"));

    // ko_jackal_10.06.15
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "BFCHG_CONV_RTO", dts_code.getCellData(add_index, "BFCHG_CONV_RTO"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "AFCHG_CONV_RTO", dts_code.getCellData(add_index, "AFCHG_CONV_RTO"));
};
scwin.fn_add = function() {
    for (i = 1; i <= dts_selectleadcom.getTotalRow(); i++) {
        if (dts_selectleadcom.getCellData(i, "ISU_CD") == dts_code.getCellData(dts_code.getRowPosition(), "ISU_CD")) {
            return;
        }
    }
    scwin.fn_add_dts_select(dts_code.getRowPosition());
    dts_selectleadcom.sort("+ISU_NM", 0);
    //dts_selectleadcom.sort(); // W-Craft 주석처리 

};
scwin.fn_add_all = function() {
    dts_selectleadcom.removeAll();
    grd_selectleadcom.redraw = false;
    for (i = 1; i <= dts_code.getTotalRow(); i++) {
        scwin.fn_add_dts_select(i);
    }
    grd_selectleadcom.redraw = true;
    grd_selectleadcom.focus();
    dts_selectleadcom.setRowPosition("1", 0);

    //dts_selectleadcom.SortExpr="+ISU_NM";
    //dts_selectleadcom.Sort();

};
scwin.fn_del = function() {
    //var RowPos = dts_selectleadcom.ValueRow(dts_selectleadcom.RowPosition, MTr_2.ItemText);
    var RowPos = dts_selectleadcom.getRowPosition();
    $c.cp.removeRow(dts_selectleadcom, RowPos);
};
scwin.fn_del_all = function() {
    dts_selectleadcom.removeAll();
};
scwin.fn_confirm = async function() {
    scwin.fn_SetPar(dts_selectleadcom);
    await $c.frame.CloseFrame();
};
scwin.fn_set_code = function() {
    dts_code.DataID = "/etn/EtnCodeAct.do?method=searchEtnCode&GUBUN=" + scwin.keyGubun + "&ISUR_CD=" + scwin.keyIsurCd;
    dts_code.Reset();
};
scwin.gform_onload = function() {
    gform.scroll = "no";
    var arrPar = new Array();
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar, dts_selectleadcom);
        scwin.keyIsurCd = (arrPar.length >= 1 ? arrPar[0] : "");
        scwin.keyGubun = (arrPar.length >= 2 ? arrPar[1] : "");

        // elw 종목 조회 보내기
        scwin.fn_set_code();
    }
};
scwin.grd_leadcom_OnDblClick = function(row, colid) {
    scwin.fn_add();
};
scwin.grd_selectleadcom_OnDblClick = function(row, colid) {
    scwin.fn_del();
};
scwin.btn_confirm_onclick = function() {
    scwin.fn_confirm();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_code_OnLoadError = function() {
    $c.stf.alert_error(dts_code);
};
scwin.dts_code_OnFail = function() {
    $c.stf.alert_error(dts_code);
};
scwin.dts_selectleadcom_OnLoadError = function() {
    $c.stf.alert_error(dts_selectleadcom);
};
scwin.dts_selectleadcom_OnFail = function() {
    $c.stf.alert_error(dts_selectleadcom);
};
scwin.img_rightarr_onclick = function() {
    scwin.fn_add();
};
scwin.img_leftarr_onclick = function() {
    scwin.fn_del();
};
scwin.img_rightarr_all_onclick = function() {
    scwin.fn_add_all();
};
scwin.img_leftarr_all_onclick = function() {
    scwin.fn_del_all();
};
